#!/usr/bin/env python3
"""Offline AI-v3 updater. Run in project root. No API calls or DB changes.
Default: preflight all files, back up, apply, build (rollback if build fails).
--check: check only. --no-build: apply without build. --rollback PATH: restore code.
Stop the bot and other editors before running. Payload is embedded below.
"""
import argparse, base64, datetime, hashlib, io, json, os, pathlib, shutil, subprocess, sys, tempfile, zipfile
PAYLOAD = ''

def digest(data):
    return hashlib.sha256(data).hexdigest()

def checked_path(root, relative):
    rel = pathlib.PurePosixPath(relative)
    if rel.is_absolute() or '..' in rel.parts or not rel.parts:
        raise RuntimeError('Invalid package path')
    target = root
    for part in rel.parts:
        target = target / part
        if target.is_symlink():
            raise RuntimeError('Символічне посилання: ' + relative)
    return target

def atomic(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    handle, name = tempfile.mkstemp(prefix='.ai-v3-', dir=path.parent)
    try:
        with os.fdopen(handle, 'wb') as stream:
            stream.write(data)
        if path.exists(): os.chmod(name, path.stat().st_mode & 0o777)
        else: os.chmod(name, 0o644)
        os.replace(name, path)
    finally:
        if os.path.exists(name): os.unlink(name)

def merge(current, baseline, updated):
    if not shutil.which('git'):
        return None
    with tempfile.TemporaryDirectory(prefix='ai-v3-merge-') as directory:
        paths = [pathlib.Path(directory)/name for name in ('current','base','updated')]
        for path, data in zip(paths, (current, baseline, updated)):
            path.write_bytes(data.replace(b'\r\n', b'\n'))
        result = subprocess.run(['git','merge-file','-p',str(paths[0]),str(paths[1]),str(paths[2])], capture_output=True)
        return result.stdout if result.returncode == 0 else None

def load_package():
    archive = zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD)))
    manifest = json.loads(archive.read('manifest.json'))
    for item in manifest:
        if digest(archive.read('updated/'+item['path'])) != item['updatedSha256']:
            raise RuntimeError('Пошкоджено пакет')
        if item['baselineSha256'] and digest(archive.read('base/'+item['path'])) != item['baselineSha256']:
            raise RuntimeError('Пошкоджено базову копію')
    return archive, manifest

def rollback(root, folder, allowed):
    folder = pathlib.Path(folder).resolve()
    if folder.parent != root or not folder.name.startswith('ai-v3-backup-'):
        raise RuntimeError('Очікується папка ai-v3-backup-* у корені проєкту')
    entries = json.loads((folder/'backup.json').read_text())
    for item in entries:
        if item['path'] not in allowed: raise RuntimeError('Невідомий шлях у резервній копії')
        path = checked_path(root, item['path'])
        if not path.is_file() or digest(path.read_bytes()) != item['afterSha256']:
            raise RuntimeError('Після встановлення файл змінено; автоматичне відновлення зупинено: '+item['path'])
        if item['existed']:
            old = checked_path(folder/'files',item['path'])
            if digest(old.read_bytes()) != item['beforeSha256']: raise RuntimeError('Резервну копію змінено')
    for item in entries:
        path = checked_path(root,item['path'])
        if item['existed']: atomic(path, checked_path(folder/'files',item['path']).read_bytes())
        else: path.unlink()
    print('Попередній код відновлено. База даних не змінювалася.')

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--no-build',action='store_true')
    parser.add_argument('--rollback')
    args = parser.parse_args()
    root = pathlib.Path.cwd().resolve()
    if not (root/'src/Bot/Bot.csproj').is_file():
        raise RuntimeError('Запусти з кореня бота, де є src/Bot/Bot.csproj')
    archive, manifest = load_package()
    if args.rollback:
        rollback(root,args.rollback,{x['path'] for x in manifest}); return 0
    allowed_migrations = {'20260912171513_Initial.cs','20260912171513_Initial.Designer.cs',
        '20260916232017_AddConversationState.cs','20260916232017_AddConversationState.Designer.cs','BotDbModelSnapshot.cs'}
    migrations = checked_path(root,'src/Bot/Infrastructure/Persistence/Migrations')
    unknown = [p.name for p in migrations.glob('*.cs') if p.name not in allowed_migrations]
    if unknown: raise RuntimeError('Є додаткові міграції; потрібне узгодження: '+', '.join(unknown))
    planned, conflicts = [], []
    prompt = 'src/Bot/Resources/Prompts/chat-v1.txt'
    for item in manifest:
        rel = item['path']; path = checked_path(root,rel)
        if path.exists() and not path.is_file():
            conflicts.append(rel); continue
        current = path.read_bytes() if path.exists() else None
        updated = archive.read('updated/'+rel)
        if current == updated: continue
        if item['operation'] == 'create':
            if current is not None: conflicts.append(rel); continue
            result = updated
        elif current is None:
            conflicts.append(rel); continue
        elif digest(current) == item['baselineSha256'] or rel == prompt:
            # Replacing the old persona is explicitly part of this requested update.
            result = updated
        else:
            result = merge(current,archive.read('base/'+rel),updated)
            if result is None: conflicts.append(rel); continue
        if result != current: planned.append((item,current,result))
    if conflicts:
        print('ЗМІНИ НЕ ВНЕСЕНО. Не вдалося автоматично поєднати:')
        for rel in conflicts: print('  '+rel)
        print('Скопіюй цей список у чат. Не потрібно змінювати решту файлів вручну.')
        return 2
    if not planned:
        print('Оновлення вже встановлено.'); return 0
    print('Готово до встановлення: '+str(len(planned))+' файлів.')
    if args.check: print('Режим перевірки: файли не змінено.'); return 0
    if not args.no_build and (not shutil.which('bash') or not (root/'scripts/dotnet.sh').is_file()):
        raise RuntimeError('Потрібен bash і scripts/dotnet.sh. Запускай у Shell Replit.')
    stamp = datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d-%H%M%S-%f')
    backup = root/('ai-v3-backup-'+stamp); backup.mkdir(mode=0o700)
    entries = []
    for item,current,result in planned:
        rel=item['path']
        if current is not None:
            destination=checked_path(backup/'files',rel)
            destination.parent.mkdir(parents=True,exist_ok=True);destination.write_bytes(current)
        entries.append({'path':rel,'existed':current is not None,
            'beforeSha256':digest(current) if current is not None else None,'afterSha256':digest(result)})
    (backup/'backup.json').write_text(json.dumps(entries,indent=2))
    applied=[]
    try:
        for item,current,result in planned:
            path=checked_path(root,item['path'])
            now=path.read_bytes() if path.exists() else None
            if now != current: raise RuntimeError('Файл змінився під час встановлення: '+item['path'])
            atomic(path,result);applied.append((path,current,result))
        if not args.no_build:
            print('Перевіряю Release-збірку...',flush=True)
            result=subprocess.run(['bash','scripts/dotnet.sh','build','src/Bot','-c','Release'],cwd=root)
            if result.returncode: raise RuntimeError('Збірка не пройшла')
    except BaseException:
        # Roll back only our writes; preserve concurrent edits if any.
        for path,current,result in reversed(applied):
            if path.exists() and path.read_bytes()==result:
                if current is None: path.unlink()
                else: atomic(path,current)
        print('Встановлення перервано; внесені нами зміни коду відкочено. Копія: '+backup.name)
        raise
    print('ГОТОВО. Код AI v3 встановлено.')
    print('Резервна копія: '+backup.name)
    print('Базу даних і Secrets інсталятор не змінював.')
    print('Далі запусти: bash scripts/run.sh')
    print('Ця команда застосує міграцію нової таблиці й запустить бот.')
    print('Скасувати зміни коду: python3 install_ai_v3.py --rollback '+backup.name)
    return 0

if __name__=='__main__':
    try: sys.exit(main())
    except KeyboardInterrupt: print('Перервано.');sys.exit(130)
    except Exception as error:
        print('Помилка: '+str(error));sys.exit(1)
